const searchKnowledgeText = `-- name: SearchKnowledgeText :many
SELECT c.id, c.heading, c.anchor, left(c.content, 600)::text AS snippet, d.path, d.commit_sha, s.repo,
  greatest(ts_rank(to_tsvector('english', c.heading || ' ' || c.content), websearch_to_tsquery('english', $1::text)),
           word_similarity($1::text, c.heading || ' ' || left(c.content, 4000)))::float8 AS rank
FROM knowledge_chunks c
JOIN knowledge_docs d ON d.id = c.doc_id
JOIN knowledge_sources s ON s.id = d.source_id
WHERE c.workspace_id = $2
  AND (to_tsvector('english', c.heading || ' ' || c.content) @@ websearch_to_tsquery('english', $1::text)
       OR word_similarity($1::text, c.heading || ' ' || left(c.content, 4000)) > 0.4)
ORDER BY rank DESC
LIMIT $3
`

type SearchKnowledgeTextParams struct {
	Query       string    `json:"query"`
	WorkspaceID uuid.UUID `json:"workspace_id"`
	Lim         int32     `json:"lim"`
}

type SearchKnowledgeTextRow struct {
	ID        uuid.UUID `json:"id"`
	Heading   string    `json:"heading"`
	Anchor    string    `json:"anchor"`
	Snippet   string    `json:"snippet"`
	Path      string    `json:"path"`
	CommitSha string    `json:"commit_sha"`
	Repo      string    `json:"repo"`
	Rank      float64   `json:"rank"`
}

func (q *Queries) SearchKnowledgeText(ctx context.Context, arg SearchKnowledgeTextParams) ([]SearchKnowledgeTextRow, error) {
	rows, err := q.db.Query(ctx, searchKnowledgeText, arg.Query, arg.WorkspaceID, arg.Lim)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []SearchKnowledgeTextRow{}
	for rows.Next() {
		var i SearchKnowledgeTextRow
		if err := rows.Scan(
			&i.ID,
			&i.Heading,
			&i.Anchor,
			&i.Snippet,
			&i.Path,
			&i.CommitSha,
			&i.Repo,
			&i.Rank,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const searchKnowledgeVector = `-- name: SearchKnowledgeVector :many
SELECT c.id, c.heading, c.anchor, left(c.content, 600)::text AS snippet, d.path, d.commit_sha, s.repo,
  (1 - (e.embedding <=> $1::vector))::float8 AS rank
FROM embeddings e
JOIN knowledge_chunks c ON c.id = e.entity_id AND c.workspace_id = e.workspace_id
JOIN knowledge_docs d ON d.id = c.doc_id
JOIN knowledge_sources s ON s.id = d.source_id
WHERE e.workspace_id = $2 AND e.entity_type = 'knowledge_chunk' AND e.model = $3 AND e.dims = $4
ORDER BY e.embedding <=> $1::vector
LIMIT $5
`

