const updateKnowledgeSource = `-- name: UpdateKnowledgeSource :one
UPDATE knowledge_sources SET name = $3, repo = $4, branch = $5, path_prefix = $6, exclude = $7,
  token_secret_id = $8, token_env = $9, enabled = $10,
  -- a changed location must be re-read from scratch
  last_commit = CASE WHEN repo = $4 AND branch = $5 AND path_prefix = $6 AND exclude = $7 THEN last_commit ELSE NULL END
WHERE workspace_id = $1 AND id = $2
RETURNING id, workspace_id, name, kind, repo, branch, path_prefix, exclude, token_secret_id, token_env, enabled, last_commit, last_synced_at, last_error, status, created_at
`

type UpdateKnowledgeSourceParams struct {
	WorkspaceID   uuid.UUID  `json:"workspace_id"`
	ID            uuid.UUID  `json:"id"`
	Name          string     `json:"name"`
	Repo          string     `json:"repo"`
	Branch        string     `json:"branch"`
	PathPrefix    string     `json:"path_prefix"`
	Exclude       []string   `json:"exclude"`
	TokenSecretID *uuid.UUID `json:"token_secret_id"`
	TokenEnv      *string    `json:"token_env"`
	Enabled       bool       `json:"enabled"`
}

func (q *Queries) UpdateKnowledgeSource(ctx context.Context, arg UpdateKnowledgeSourceParams) (KnowledgeSource, error) {
	row := q.db.QueryRow(ctx, updateKnowledgeSource,
		arg.WorkspaceID,
		arg.ID,
		arg.Name,
		arg.Repo,
		arg.Branch,
		arg.PathPrefix,
		arg.Exclude,
		arg.TokenSecretID,
		arg.TokenEnv,
		arg.Enabled,
	)
	var i KnowledgeSource
	err := row.Scan(
		&i.ID,
		&i.WorkspaceID,
		&i.Name,
		&i.Kind,
		&i.Repo,
		&i.Branch,
		&i.PathPrefix,
		&i.Exclude,
		&i.TokenSecretID,
		&i.TokenEnv,
		&i.Enabled,
		&i.LastCommit,
		&i.LastSyncedAt,
		&i.LastError,
		&i.Status,
		&i.CreatedAt,
	)
	return i, err
}

const upsertKnowledgeDoc = `-- name: UpsertKnowledgeDoc :one
INSERT INTO knowledge_docs (workspace_id, source_id, path, blob_sha, commit_sha, title, content)
VALUES ($1, $2, $3, $4, $5, $6, $7)
ON CONFLICT (source_id, path) DO UPDATE
  SET blob_sha = EXCLUDED.blob_sha, commit_sha = EXCLUDED.commit_sha, title = EXCLUDED.title, content = EXCLUDED.content, updated_at = now()
RETURNING id
`

type UpsertKnowledgeDocParams struct {
	WorkspaceID uuid.UUID `json:"workspace_id"`
	SourceID    uuid.UUID `json:"source_id"`
	Path        string    `json:"path"`
	BlobSha     string    `json:"blob_sha"`
	CommitSha   string    `json:"commit_sha"`
	Title       string    `json:"title"`
	Content     string    `json:"content"`
}

func (q *Queries) UpsertKnowledgeDoc(ctx context.Context, arg UpsertKnowledgeDocParams) (uuid.UUID, error) {
	row := q.db.QueryRow(ctx, upsertKnowledgeDoc,
		arg.WorkspaceID,
		arg.SourceID,
		arg.Path,
		arg.BlobSha,
		arg.CommitSha,
		arg.Title,
		arg.Content,
	)
	var id uuid.UUID
	err := row.Scan(&id)
	return id, err
}

